use rstsr::prelude::*;

use super::CATEGORY;
use crate::TESTCFG;

#[cfg(test)]
mod doc_ext_matmul {
    use super::*;
    static FUNC: &str = "doc_ext_matmul";

    #[test]
    fn test_doc() {
        crate::specify_test!("test_doc");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        let a = rt::tensor_from_nested!([[1u8, 2], [3, 4]], &device);
        let b = rt::tensor_from_nested!([[5u16, 6], [7, 8]], &device);
        let c = rt::ext_matmul(&a, &b);
        println!("{c}");
        // [[ 19 22]
        //  [ 43 50]]
        assert_eq!(format!("{c}"), "[[ 19 22]\n [ 43 50]]");

        // RowMajor: the matrix dimensions are the last two axes, so the leading axes are batch
        let a = rt::arange((24, &device)).into_shape([2, 3, 4]);
        let b = rt::arange((40, &device)).into_shape([2, 4, 5]);
        println!("{:?}", rt::ext_matmul(&a, &b).shape());
        // [2, 3, 5]
        assert_eq!(rt::ext_matmul(&a, &b).shape(), &[2, 3, 5]);

        // ColMajor: the matrix dimensions are the first two axes, so the trailing axes are batch
        device.set_default_order(ColMajor);
        let a = rt::arange((24, &device)).into_shape([3, 4, 2]);
        let b = rt::arange((40, &device)).into_shape([4, 5, 2]);
        println!("{:?}", rt::ext_matmul(&a, &b).shape());
        // [3, 5, 2]
        assert_eq!(rt::ext_matmul(&a, &b).shape(), &[3, 5, 2]);
    }
}

